def last_Digit_Factorial(n):
    # Handling special cases where factorial is 0 or 1
    if n == 0 or n == 1:
        return 1
    # For n > 4, the factorial will always end in 0 because it will contain at least one 2 and one 5 as factors
    if n > 4:
        return 0
    # For n = 2, 3, 4, calculate factorial and return last digit
    if n == 2:
        return 2
    elif n == 3:
        return 6
    elif n == 4:
        return 4
    # For other cases, calculate factorial iteratively and return last digit
    else:
        last_digit = 1
        for i in range(2, n + 1):
            last_digit = (last_digit * i) % 10
        return last_digit
```

