def lbs(nums):
    n = len(nums)
    if n == 0:
        return 0

    # Initialize arrays to store the length of the longest increasing and decreasing subsequences
    inc = [1] * n
    dec = [1] * n

    # Compute the length of the longest increasing subsequence ending at each index
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                inc[i] = max(inc[i], inc[j] + 1)

    # Compute the length of the longest decreasing subsequence starting at each index
    for i in range(n-2, -1, -1):
        for j in range(n-1, i, -1):
            if nums[i] > nums[j]:
                dec[i] = max(dec[i], dec[j] + 1)

    # Find the maximum value between the longest increasing and decreasing subsequences
    return max(inc[i] + dec[i] - 1 for i in range(n))

