def toggle_middle_bits(n):
    # Convert the number to its binary representation as an integer
    bin_n = bin(n)[2:]
    # Calculate the length of the binary representation
    length = len(bin_n)
    # Toggle the bits from the second to the second last (1-based index)
    for i in range(1, length - 1):
        if bin_n[i] == '0':
            bin_n = bin_n[:i] + '1' + bin_n[i+1:]
        else:
            bin_n = bin_n[:i] + '0' + bin_n[i+1:]
    # Convert the binary string back to an integer
    return int(bin_n, 2)
