def max_sum_increasing_subsequence(arr, n):
    if n == 0:
        return 0

    # Initialize the dp array
    dp = [0] * n
    dp[0] = arr[0]

    # Fill the dp array
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and dp[i] < dp[j] + arr[i]:
                dp[i] = dp[j] + arr[i]
        if dp[i] == 0:
            dp[i] = arr[i]

    # Return the maximum value in dp array
    return max(dp)

